{
  "name": "Prospect Park",
  "location": "Brooklyn, New York City",
  "history": [
    {
      "period": "Before the park",
      "description": "The land includes Battle Pass, a site associated with the 1776 Battle of Long Island during the American Revolution."
    },
    {
      "period": "1850s–1860s",
      "description": "As Brooklyn grew, civic leaders sought a large public park. Landscape architects Frederick Law Olmsted and Calvert Vaux, who had designed Central Park, developed the plan for Prospect Park."
    },
    {
      "period": "1866–1873",
      "description": "Construction began in 1866. The park opened to the public in 1867, while work continued into the early 1870s. Its design brought together the Long Meadow, wooded Ravine and lake to offer contrasting landscapes within the city."
    },
    {
